def f(g):
    g=[r[:] for r in g]
    h,w=len(g),len(g[0])
    rs=[i for i,r in enumerate(g) if 5 in r]
    cs=[j for j,c in enumerate(zip(*g)) if c.count(5)>0]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # frames: sizes n, n-2, ... down to 4 (or 5 if odd), color alternates 5,2,...; remainder filled with next color if size<3
    size=n=r1-r0+1
    col=5
    while size>=4:
        for i in range(r0+(n-size)//2, r0+(n-size)//2+size):
            for j in range(c0+(n-size)//2, c0+(n-size)//2+size):
                if (i==r0+(n-size)//2 or i==r0+(n-size)//2+size-1 or j==c0+(n-size)//2 or j==c0+(n-size)//2+size-1) and g[i][j]==0:
                    g[i][j]=col
        size-=2; col=3-col
    if size<=2:
        rr=c0+(n-size)//2; cc=r0+(n-size)//2
        for i in range(cc,cc+size):
            for j in range(rr,rr+size):
                if g[i][j]==0: g[i][j]=col
    return g
