    g=[r[:] for r in g]
    H,W=len(g),len(g[0])
    # outer frame: top row of nonzero = border; find min/max rows/cols with nonzero
    nz=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=0]
    r0=min(i for i,_ in nz); r1=max(i for i,_ in nz)
    c0=min(j for _,j in nz); c1=max(j for _,j in nz)
    out=[r[:] for r in g]
    # fill everything inside with 2, then draw nested boxes shrinking by 1 each side
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            out[i][j]=2
    def rec(y0,y1,x0,x1,depth):
        w=x1-x0-1; h=y1-y0-1
        if depth==0 or w<0 or h<0: return
        c=5 if depth%2==0 else 2
        # paint perimeter
        for i in range(y0+1,y1):
            if x0<=x0 and x1>=x1: pass
        for i in range(y0+1,y1+1):
            for j in (x0,x1):
                if out[i][j]==0: out[i][j]=c
        for j in range(x0+1,x1+1):
            for i in (y0,y1):
                if out[i][j]==0: out[i][j]=c
        rec(y0+2,y1-2,x0+2,x1-2,depth-1)
    rec(r0+1,r1-1,c0+1,c1-1,3)
    return out
