    Z=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==0]
    # connected components
    comps=[];seen=set()
    for p in Z:
        if p in seen: continue
        s=[p];seen.add(p);cells=set();c=[]
        while s:
            i,j=s.pop();cells.add((i,j));c.append((i,j))
